package net.atlasauth.pca.verifier

import java.nio.file.Files
import java.nio.file.Path
import java.util.zip.GZIPInputStream
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Differential against the TS reference for OracleFacts (rule 16) and ParamProvenance (rule 17): expected results are generated by
 * tools/pca-audit/java-mutate/k042-oracleprov-oracle.mjs into test-data/k042-oracleprov.json.gz. Every case compares the FULL
 * result (exact reasons, world member order, single_source, outcome, friction, labels, classes, env, read-purpose lists, flow rule).
 */
class K042OracleProvOracleTest {
    companion object {
        /** Reasons that differ BY DESIGN: a non-object input is an internal error on the JVM (the exception's simple name). */
        val JVM_REASON = mapOf(
            "world/k042-input-null" to "facts: evaluation error (fail closed): NullPointerException",
            "world/k042-input-array" to "facts: evaluation error (fail closed): ClassCastException",
            "prov/k042-input-null" to "provenance: evaluation error (fail closed): NullPointerException",
            "prov/k042-input-array" to "provenance: evaluation error (fail closed): ClassCastException",
        )
        val VALIDATORS: Map<String, (Any?) -> String?> = mapOf(
            "validateFactWire" to { o -> OracleFacts.validateFactWire(o) },
            "validateWorldPolicy" to { o -> OracleFacts.validateWorldPolicy(o) },
            "validateOfferPolicy" to { o -> OracleFacts.validateOfferPolicy(o) },
            "validateOfferSetWire" to { o -> OracleFacts.validateOfferSetWire(o) },
            "validateLabelsWire" to { o -> ParamProvenance.validateLabelsWire(o) },
            "validateFlowRules" to { o -> ParamProvenance.validateFlowRules(o) },
            "validateProvenancePolicy" to { o -> ParamProvenance.validateProvenancePolicy(o) },
            "validateProvWire" to { o -> ParamProvenance.validateProvWire(o) },
        )
        val cases: List<Any?> by lazy {
            GZIPInputStream(Files.newInputStream(Path.of("test-data/k042-oracleprov.json.gz"))).use {
                IntentJs.arr(IntentJs.get(IntentJs.normalize(Json.parseLenient(String(it.readAllBytes(), Charsets.UTF_8))), "cases"))
            }
        }

        /** JSON text keeping member ORDER, numbers by value. */
        fun ser(v: Any?): String = when (v) {
            null -> "null"
            is String -> Json.canonicalize(v)
            is Boolean -> v.toString()
            is Map<*, *> -> v.entries.joinToString(",", "{", "}") { Json.canonicalize(it.key) + ":" + ser(it.value) }
            is List<*> -> v.joinToString(",", "[", "]") { ser(it) }
            is Long, is Int -> v.toString()
            else -> {
                val d = IntentJs.num(v)
                if (d != null) (if (d == Math.rint(d) && Math.abs(d) < 1e17) d.toLong().toString() else d.toString()) else "<${v.javaClass.simpleName}:$v>"
            }
        }
        fun reasonWant(name: String, ts: Any?): String? = if (JVM_REASON.containsKey(name)) JVM_REASON[name] else ts as String?
    }

    @Test fun oracle() {
        assertTrue("only ${cases.size} cases", cases.size > 1900)
        val errs = ArrayList<String>(); var pinned = 0
        for (co in cases) {
            val c = IntentJs.obj(co)
            val name = c["name"] as String
            val got: String; val want: String
            try {
                when (val kind = c["kind"] as String) {
                    "fn" -> { got = ser(VALIDATORS[c["fn"] as String]!!(c["arg"])); want = ser(c["want"]) }
                    "ratio" -> { got = ser(OracleFacts.ratioPpm(IntentJs.lng(c["a"]), IntentJs.lng(c["b"]))); want = ser(c["want"]) }
                    "flowRule" -> { got = ser(ParamProvenance.flowRuleFor(IntentJs.obj(c["rules"]), c["cls"] as String)); want = ser(c["want"]) }
                    "flowAllowed" -> {
                        got = ser(ParamProvenance.flowAllowed(IntentJs.obj(c["rules"]), c["cls"] as String, c["origin"] as String, c["aud"] as String))
                        want = ser(c["want"])
                    }
                    "active" -> { got = ser(OracleFacts.intentWorldActive(c["committed"], c["policy"])); want = ser(c["expect"]) }
                    "read" -> {
                        val r = ParamProvenance.decideReadPurpose(c["input"])
                        got = ser(linkedMapOf("outcome" to r.outcome, "minimise" to r.minimise, "uncovered" to r.uncovered))
                        val e = IntentJs.obj(c["expect"])
                        want = ser(linkedMapOf("outcome" to e["outcome"], "minimise" to e["minimise"], "uncovered" to e["uncovered"]))
                    }
                    "world" -> {
                        val r = OracleFacts.decideIntentWorld(c["input"])
                        val e = IntentJs.obj(c["expect"])
                        got = if (r.ok) "ok ${ser(r.world)} ${ser(r.singleSource)} ${ser(r.reason)}" else "fail ${ser(r.reason)} ${ser(r.world)} ${ser(r.singleSource)}"
                        want = if (e["ok"] == true) "ok ${ser(e["world"])} ${ser(e["single_source"])} null" else "fail ${ser(reasonWant(name, e["reason"]))} null null"
                        if (JVM_REASON.containsKey(name)) pinned++
                    }
                    "prov" -> {
                        val r = ParamProvenance.decide(c["input"])
                        val e = IntentJs.obj(c["expect"])
                        got = listOf(r.outcome, ser(r.reason), ser(r.friction), ser(r.labels), ser(r.classes), ser(r.env)).joinToString(" | ")
                        want = listOf(e["outcome"] as String, ser(reasonWant(name, e["reason"])), ser(e["friction"]), ser(e["labels"]), ser(e["classes"]), ser(e["env"])).joinToString(" | ")
                        if (JVM_REASON.containsKey(name)) pinned++
                    }
                    else -> throw AssertionError("unknown kind $kind")
                }
            } catch (ex: RuntimeException) { errs.add("$name threw $ex"); continue }
            if (got != want) errs.add("$name\n    got  $got\n    want $want")
        }
        assertEquals("every pinned divergence names a case", JVM_REASON.size, pinned)
        assertTrue("${errs.size} mismatches:\n" + errs.take(60).joinToString("\n"), errs.isEmpty())
    }
}
